function descendingComparator(a, b, orderBy) {
  if (b[orderBy] < a[orderBy]) {
    return -1;
  }
  if (b[orderBy] > a[orderBy]) {
    return 1;
  }
  return 0;
}

function getComparator(order, orderBy) {
  return order === 'desc'
    ? (a, b) => descendingComparator(a, b, orderBy)
    : (a, b) => -descendingComparator(a, b, orderBy);
}

const ColorButton = styled(Button)(({ theme }) => ({
  color: 'white',
  backgroundColor: 'red',
}));
const label = { inputProps: { 'aria-label': 'Size switch demo' } };

export default function UserPage() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)
  
  const [search, setsearch] = useState('');
  const [page, setPage] = useState(parseInt(queryParams.get('page'),10) || 1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'),10) || 10);
  const [notoficationList, setnotoficationList] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [userList, setUserList] = useState([]);
  const [providerList, setProviderList] = useState([]);
  const isMobile = useResponsive('down', 'sm')
  const {i18} = useMyContext();

  const TABLE_HEAD = [
    // { id: 'notificationId', label: 'NotificationId', alignRight: false },
    { id: 'notificationcreated', label: i18?.ADMIN_NOTIFICATION?.CREATED || 'Created', alignRight: false },
    // { id: 'forWhom', label: 'ForWhom', alignRight: false },
    { id: 'fromWhom', label: i18?.ADMIN_NOTIFICATION?.FROMWHOM || 'FromWhom', alignRight: false },
    { id: 'userType', label: i18?.ADMIN_NOTIFICATION?.USERTYPE || 'UserType', alignRight: false },
    { id: 'message', label: i18?.ADMIN_NOTIFICATION?.MESSAGE || 'Message', alignRight: false },
    { id: 'status', label: i18?.ADMIN_NOTIFICATION?.STATUS || 'Status', alignRight: false },
    { id: 'action', label: i18?.ADMIN_NOTIFICATION?.ACTION || 'Action', alignRight: false },
  ];

  const fetchData = async () => {
    try {
      const url = `module/notifications/lists?_page=${page}&_limit=${rowsPerPage}`;
      const res = await axios.get(url);
      if (res.status === 200) {
        setnotoficationList(res.data.data.notifications);
        setTotalCount(res.data.data.totalCount);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const deleteNotification = async (id) => {
    try {
      const res = await axios.put(`/module/notifications/${id}`);
      if (res.status === 200) {
        fetchData();
        GenerateToastConfig(res.data.message, 'success');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };
  // const fetchUserList = async () => {
  //   try {
  //     const response = await axios.get(`module/auth/users?_page=1&_limit=10`);
  //     setUserList(response.data.data);
  //   } catch (error) {
  //     console.error('Error fetching user list:', error);
  //   }
  // };

  // const fetchProviderList = async () => {
  //   try {
  //     const response = await axios.get(`module/auth/providers?_page=1&_limit=10`);
  //     setProviderList(response.data.data);
  //   } catch (error) {
  //     console.error('Error fetching provider list:', error);
  //   }
  // };

  useEffect(() => {
    fetchData();
    // fetchUserList();
    // fetchProviderList();
  }, [page, rowsPerPage, order, orderBy, search]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleClick = (event, name) => {
    const selectedIndex = selected.indexOf(name);
    let newSelected = [];
    if (selectedIndex === -1) {
      newSelected = newSelected.concat(selected, name);
    } else if (selectedIndex === 0) {
      newSelected = newSelected.concat(selected.slice(1));
    } else if (selectedIndex === selected.length - 1) {
      newSelected = newSelected.concat(selected.slice(0, -1));
    } else if (selectedIndex > 0) {
      newSelected = newSelected.concat(selected.slice(0, selectedIndex), selected.slice(selectedIndex + 1));
    }
    setSelected(newSelected);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };
  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = notoficationList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };
  return (
    <>
      <Helmet>
        <title>List Notification </title>
      </Helmet>

      <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
        <Typography variant="h4" gutterBottom>
          {i18?.ADMIN_NOTIFICATION?.LISTINGNOTIFICATIONS || "Listing Notifications"}
        </Typography>
      </Stack>
      <Card>
        <Scrollbar>
          <TableContainer sx={{ minWidth: 800 }}>
            <Table>
              <UserListHead
                order={order}
                orderBy={orderBy}
                headLabel={TABLE_HEAD}
                rowCount={notoficationList.length}
                numSelected={selected.length}
                onRequestSort={handleRequestSort}
                onSelectAllClick={handleSelectAllClick}
              />
              <TableBody>
                {notoficationList.map((row) => {
                  const { id, forWhom, fromWhom, userType, name } = row;
                  const selectedUser = selected.indexOf(name) !== -1;

                  const user = userList.find((user) => user._id === forWhom);

                  const provider = providerList.find((provider) => provider._id === forWhom);

                  const dateObjectCreated = new Date(row?.createdAt);

                  const formattedCreated = `${dateObjectCreated.getDate()}-${
                    dateObjectCreated.getMonth() + 1
                  }-${dateObjectCreated.getFullYear()}`;

                  return (
                    <TableRow
                      sx={{
                        '&:nth-of-type(odd)': {
                          backgroundColor: '#DDDDDD',
                        },
                        '&:last-child td, &:last-child th': {
                          border: 0,
                        },
                      }}
                      key={id}
                      tabIndex={-1}
                      role="checkbox"
                      selected={selectedUser}
                    >
                      <TableCell padding="checkbox">
                        {/* <Checkbox checked={selectedUser} onChange={(event) => handleClick(event, name)} /> */}
                      </TableCell>
                      {/* <TableCell align="left">{row._id}</TableCell> */}
                      <TableCell align="left" style={{ whiteSpace: 'nowrap' }}>
                        {formattedCreated}
                        {/* {row.createdAt?.split('T')[0]} */}
                      </TableCell>
                      {/* <TableCell align="left">
                        {row.userType === 'USER' ? (user ? `${user.firstname} ${user.lastname}` : '') : ''}
                        {row.userType === 'PROVIDER'
                          ? provider
                            ? `${provider.firstname} ${provider.lastname}`
                            : ''
                          : ''}
                      </TableCell> */}

                      <TableCell align="left">{row.fromWhom}</TableCell>
                      <TableCell align="left">{row.userType}</TableCell>
                      <TableCell align="left">{row.message}</TableCell>
                      <TableCell align="left">
                        <Label color="success">{row.status}</Label>
                      </TableCell>
                      <TableCell>
                        <IconButton onClick={() => deleteNotification(row._id)} >
                          <Iconify icon={'eva:trash-2-outline'} />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
              {notoficationList.length === 0 && (
                <TableBody>
                  <TableRow>
                    <TableCell align="center" colSpan={12} sx={{ py: 3 }}>
                      <Paper
                        sx={{
                          textAlign: 'center',
                        }}
                      >
                        <Typography variant="h6" paragraph>
                          Not found
                        </Typography>
                      </Paper>
                    </TableCell>
                  </TableRow>
                </TableBody>
              )}
            </Table>
          </TableContainer>
        </Scrollbar>
      </Card>
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />
     
      <></>
    </>
  );
} 
